CREATE TABLE `resource_grant_operations` (`id` CHAR(36) CHARACTER SET ascii NOT NULL,`organization_id` CHAR(36) CHARACTER SET ascii NOT NULL,`actor_id` CHAR(36) CHARACTER SET ascii NOT NULL,`operation` VARCHAR(80) CHARACTER SET ascii NOT NULL,`idempotency_key_hash` CHAR(64) CHARACTER SET ascii NOT NULL,`request_hash` CHAR(64) CHARACTER SET ascii NOT NULL,`grant_id` CHAR(36) CHARACTER SET ascii NOT NULL,`grant_version` INT UNSIGNED NOT NULL,`created_at` DATETIME(3) NOT NULL,PRIMARY KEY(`id`),UNIQUE KEY `uq_resource_grant_operation`(`actor_id`,`operation`,`idempotency_key_hash`),KEY `idx_resource_grant_operations_org`(`organization_id`,`created_at`),CONSTRAINT `fk_resource_grant_operations_org` FOREIGN KEY(`organization_id`) REFERENCES `organizations`(`id`) ON DELETE RESTRICT,CONSTRAINT `fk_resource_grant_operations_actor` FOREIGN KEY(`actor_id`) REFERENCES `users`(`id`) ON DELETE RESTRICT,CONSTRAINT `fk_resource_grant_operations_grant` FOREIGN KEY(`grant_id`) REFERENCES `resource_grants`(`id`) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
